--
-- Name: admin_address_ban_covering_v1(inet, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.admin_address_ban_covering_v1(p_address inet, p_now timestamp with time zone) RETURNS TABLE(ban_id uuid, address_range text, scope text, expires_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT b.ban_id, b.address_range::text, b.scope, b.expires_at
FROM public.address_bans b
WHERE b.lifted_at IS NULL AND b.address_range >>= p_address
    AND b.expires_at > p_now
ORDER BY CASE b.scope WHEN 'writes' THEN 3 WHEN 'sign_in' THEN 2 ELSE 1 END
    DESC, b.expires_at DESC, b.ban_id
LIMIT 1
$$;


