-- Name: admin_address_ban_edit_v2(uuid, text, text, timestamp with time zone, uuid, inet, timestamp with time zone, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.admin_address_ban_edit_v2(p_ban_id uuid, p_scope text, p_reason text, p_expires_at timestamp with time zone, p_actor_user_id uuid, p_actor_address inet, p_now timestamp with time zone, p_audit jsonb) RETURNS TABLE(status text, ban_id uuid)
