CREATE FUNCTION api.admin_audit_page_v2(p_filters jsonb, p_after jsonb, p_row_limit integer) RETURNS SETOF api.admin_audit_entry_v1
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
