--
-- Name: attachment_confirm_clean_v1(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.attachment_confirm_clean_v1(p_attachment_id uuid, p_scan_engine text, p_scanned_at timestamp with time zone) RETURNS TABLE(changed_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
BEGIN
    RETURN QUERY WITH changed AS (
      UPDATE public.attachments a SET scan_engine = p_scan_engine, scan_error = NULL, scanned_at = p_scanned_at
      WHERE a.attachment_id = p_attachment_id AND a.deleted_at IS NULL AND a.scan_status = 'clean'
      AND (a.scan_engine IS NULL OR a.scan_engine = 'format-check') RETURNING 1
    ) SELECT count(*) FROM changed;
END;
$$;


