--
-- Name: attachment_scan_failure_v1(uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.attachment_scan_failure_v1(p_attachment_id uuid, p_error text) RETURNS TABLE(changed_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
BEGIN
    RETURN QUERY WITH changed AS (
      UPDATE public.attachments a SET scan_attempts = a.scan_attempts + 1, scan_error = left(p_error,500)
      WHERE a.attachment_id = p_attachment_id RETURNING 1
    ) SELECT count(*) FROM changed;
END;
$$;


