    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.community_message_conversation_v1(p_conversation_id,
    p_user_id);
$$;


--
-- Name: community_message_conversation_with_v1(uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.community_message_conversation_with_v1(p_user_id uuid, p_username text) RETURNS TABLE(other_user_id uuid, other_username text, other_display_name text, conversation_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT u.id, u.username, u.display_name,
    (SELECT c.conversation_id FROM public.direct_conversations c
        WHERE c.first_user_id = least(p_user_id, u.id)
            AND c.second_user_id = greatest(p_user_id, u.id))
FROM public.users u
WHERE u.username = p_username AND u.deleted_at IS NULL
    AND u.status IN ('active', 'suspended');
$$;


--
-- Name: community_message_conversation_with_v2(uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.community_message_conversation_with_v2(p_user_id uuid, p_username text) RETURNS TABLE(other_user_id uuid, other_username text, other_display_name text, conversation_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.community_message_conversation_with_v1(p_user_id,
    p_username);
$$;


--
-- Name: community_message_for_report_v1(uuid, uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.community_message_for_report_v1(p_message_id uuid, p_user_id uuid) RETURNS TABLE(message_id uuid, conversation_id uuid, author_user_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT d.message_id, d.conversation_id, d.author_user_id
FROM public.direct_messages d
JOIN public.direct_conversation_members m
    ON m.conversation_id = d.conversation_id AND m.user_id = p_user_id
WHERE d.message_id = p_message_id AND d.author_user_id <> p_user_id;
$$;


