--
-- Name: community_message_inbox_v1(uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.community_message_inbox_v1(p_user_id uuid, p_after_at timestamp with time zone, p_after_id uuid, p_row_limit integer) RETURNS TABLE(conversation_id uuid, other_user_id uuid, other_username text, other_display_name text, other_gone boolean, last_message_at timestamp with time zone, unread_count integer, last_author_user_id uuid, last_excerpt text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    IF p_after_at IS NULL OR p_after_id IS NULL THEN
        RETURN QUERY
        SELECT m.conversation_id, m.other_user_id, u.username,
            u.display_name, (u.deleted_at IS NOT NULL OR u.status = 'deleted'),
            m.last_message_at, m.unread_count, latest.author_user_id,
            left(latest.body, 140)
        FROM public.direct_conversation_members m
        JOIN public.users u ON u.id = m.other_user_id
        LEFT JOIN LATERAL (
            SELECT d.author_user_id, d.body FROM public.direct_messages d
            WHERE d.conversation_id = m.conversation_id
            ORDER BY d.position DESC LIMIT 1
        ) latest ON true
        WHERE m.user_id = p_user_id
        ORDER BY m.last_message_at DESC, m.conversation_id DESC
        LIMIT p_row_limit;
    ELSE
        RETURN QUERY
        SELECT m.conversation_id, m.other_user_id, u.username,
            u.display_name, (u.deleted_at IS NOT NULL OR u.status = 'deleted'),
            m.last_message_at, m.unread_count, latest.author_user_id,
            left(latest.body, 140)
        FROM public.direct_conversation_members m
        JOIN public.users u ON u.id = m.other_user_id
        LEFT JOIN LATERAL (
            SELECT d.author_user_id, d.body FROM public.direct_messages d
            WHERE d.conversation_id = m.conversation_id
            ORDER BY d.position DESC LIMIT 1
        ) latest ON true
        WHERE m.user_id = p_user_id
            AND m.last_message_at <= p_after_at
            AND (m.last_message_at < p_after_at
                OR m.conversation_id < p_after_id)
        ORDER BY m.last_message_at DESC, m.conversation_id DESC
        LIMIT p_row_limit;
    END IF;
END;
$$;


