--
-- Name: community_message_list_v1(uuid, uuid, bigint, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.community_message_list_v1(p_conversation_id uuid, p_user_id uuid, p_before_position bigint, p_row_limit integer) RETURNS TABLE(message_id uuid, author_user_id uuid, author_username text, author_display_name text, body text, created_at timestamp with time zone, message_position bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.direct_conversation_members m
        WHERE m.conversation_id = p_conversation_id
            AND m.user_id = p_user_id) THEN
        RETURN;
    END IF;
    IF p_before_position IS NULL THEN
        RETURN QUERY
        SELECT d.message_id, d.author_user_id, a.username, a.display_name,
            d.body, d.created_at, d.position
        FROM public.direct_messages d
        JOIN public.users a ON a.id = d.author_user_id
        WHERE d.conversation_id = p_conversation_id
        ORDER BY d.position DESC
        LIMIT p_row_limit;
    ELSE
        RETURN QUERY
        SELECT d.message_id, d.author_user_id, a.username, a.display_name,
            d.body, d.created_at, d.position
        FROM public.direct_messages d
        JOIN public.users a ON a.id = d.author_user_id
        WHERE d.conversation_id = p_conversation_id
            AND d.position < p_before_position
        ORDER BY d.position DESC
        LIMIT p_row_limit;
    END IF;
END;
$$;


