CREATE FUNCTION api.community_post_likes_v1(p_post_ids uuid[], p_viewer_user_id uuid) RETURNS TABLE(post_id uuid, like_count bigint, liked boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT l.post_id, count(*)::bigint AS like_count,
    coalesce(bool_or(l.user_id = p_viewer_user_id), false) AS liked
FROM public.post_likes l
WHERE l.post_id = ANY(p_post_ids)
GROUP BY l.post_id
$$;


