--

CREATE FUNCTION api.forum_create_reply_v6(p_idempotency_key text, p_command_type text, p_actor_id text, p_request_hash text, p_command_id text, p_command_correlation_id text, p_command_at text, p_answer jsonb, p_store_refusals jsonb, p_post_id text, p_thread_id text, p_author_user_id text, p_current_body_id text, p_current_revision_id text, p_position bigint, p_visibility text, p_moderation_state text, p_version bigint, p_visibility_version bigint, p_permission_version bigint, p_hidden_at text, p_locked_at text, p_deleted_at text, p_deleted_by text, p_body_id text, p_body_post_id text, p_body_format text, p_body_source text, p_body_rendered_safe text, p_source_hash text, p_revision_id text, p_revision_post_id text, p_revision_body_id text, p_editor_user_id text, p_revision_number integer, p_edit_reason text, p_correlation_id text, p_event_id text, p_outbox_id text, p_audit_id text, p_recorded_at text, p_draft_id uuid, p_draft_revision bigint, p_post_signature jsonb) RETURNS TABLE(outcome text, response json, skipped boolean, post_id text, thread_id text, author_user_id text, current_body_id text, current_revision_id text, "position" text, visibility text, moderation_state text, version text, visibility_version text, permission_version text, hidden_at text, locked_at text, deleted_at text, deleted_by text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.forum_create_reply_v5(p_idempotency_key, p_command_type, p_actor_id, p_request_hash, p_command_id, p_command_correlation_id, p_command_at, p_answer, p_store_refusals, p_post_id, p_thread_id, p_author_user_id, p_current_body_id, p_current_revision_id, p_position, p_visibility, p_moderation_state, p_version, p_visibility_version, p_permission_version, p_hidden_at, p_locked_at, p_deleted_at, p_deleted_by, p_body_id, p_body_post_id, p_body_format, p_body_source, p_body_rendered_safe, p_source_hash, p_revision_id, p_revision_post_id, p_revision_body_id, p_editor_user_id, p_revision_number, p_edit_reason, p_correlation_id, p_event_id, p_outbox_id, p_audit_id, p_recorded_at, p_draft_id, p_draft_revision, p_post_signature);
$$;


--
-- Name: forum_draft_find_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_draft_find_v1(p_owner_user_id uuid, p_draft_id uuid, p_now timestamp with time zone) RETURNS TABLE(draft json)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT to_json(d) FROM public.forum_drafts d
JOIN public.users u ON u.id = d.owner_user_id
WHERE d.owner_user_id = p_owner_user_id AND d.draft_id = p_draft_id
    AND d.expires_at > p_now AND u.deleted_at IS NULL AND u.status = 'active';
$$;


