-- Name: forum_store_write_v2(text, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_store_write_v2(p_store_type text, p_command jsonb, p_record jsonb) RETURNS TABLE(stored json)
