--
-- Name: forum_store_write_v3(text, jsonb, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_store_write_v3(p_store_type text, p_command jsonb, p_record jsonb) RETURNS TABLE(stored json)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE result record;
BEGIN
    SELECT * INTO result FROM api.forum_store_write_v2(p_store_type, p_command, p_record);
    PERFORM api.core_forum_attach_signature_v1(result.stored::jsonb, p_command);
    RETURN QUERY SELECT result.stored;
END
$$;


