--
-- Name: forum_thread_page_head_v1(uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_thread_page_head_v1(p_thread_id uuid) RETURNS TABLE(thread_id uuid, category_id uuid, author_user_id uuid, title text, slug text, pinned boolean, visibility text, moderation_state text, locked_at timestamp with time zone, last_activity_at timestamp with time zone, deleted_at timestamp with time zone, author_username text, author_display_name text, category_title text, category_visibility text, space_id uuid, space_visibility text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT me.thread_id, me.category_id, me.author_user_id, me.title, me.slug,
    me.pinned, me.visibility, me.moderation_state, me.locked_at,
    me.last_activity_at, me.deleted_at, author.username, author.display_name,
    category.title, category.visibility, category.space_id, space.visibility
FROM public.threads me
JOIN public.users author ON author.id = me.author_user_id
JOIN public.categories category ON category.category_id = me.category_id
JOIN public.spaces space ON space.space_id = category.space_id
WHERE me.thread_id = p_thread_id
LIMIT 1
$$;


