CREATE FUNCTION api.forum_thread_page_posts_v4(p_thread_id uuid, p_standing text, p_viewer_user_id uuid, p_after_position bigint, p_after_post_id uuid, p_row_limit integer) RETURNS TABLE(post_id uuid, thread_id uuid, author_user_id uuid, current_body_id uuid, "position" bigint, visibility text, moderation_state text, created_at timestamp with time zone, deleted_at timestamp with time zone, body text, body_source text, author_username text, author_display_name text, author_avatar_id uuid)
