CREATE FUNCTION api.forum_thread_page_reads_v4(p_thread_id uuid, p_post_ids uuid[], p_viewer_user_id uuid, p_engagement_target_type text, p_link_target_type text, p_link_post_ids uuid[], p_link_row_limit integer) RETURNS TABLE(part text, ordinal bigint, post_id uuid, like_count bigint, liked boolean, reply_to_post_id uuid, reply_to_position bigint, reply_to_author_username text, thread_id uuid, slug text, name text, tag_position smallint, attachment_link_id uuid, attachment_id uuid, target_type text, target_id uuid, created_at timestamp with time zone, bookmark_id uuid, user_id uuid, note text, deleted_at timestamp with time zone, subscription_id uuid, preference text, muted_at timestamp with time zone, revoked_at timestamp with time zone, last_read_position bigint, last_read_at timestamp with time zone, reaction text, reaction_count bigint, reacted boolean)
