--
-- Name: forum_thread_placement_v1(uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_thread_placement_v1(p_source_id uuid) RETURNS TABLE(category_id uuid, category_visibility text, space_id uuid, space_visibility text, thread_author uuid, thread_visibility text, thread_deleted_at timestamp with time zone, thread_state text, category_deleted_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT c.category_id, c.visibility, c.space_id, s.visibility,
    t.author_user_id, t.visibility, t.deleted_at, t.moderation_state, c.deleted_at
FROM public.threads t
JOIN public.categories c ON c.category_id = t.category_id
JOIN public.spaces s ON s.space_id = c.space_id
WHERE t.thread_id = p_source_id
$$;


