CREATE FUNCTION api.forum_thread_placement_v2(p_source_id uuid) RETURNS TABLE(category_id uuid, category_visibility text, space_id uuid, space_visibility text, thread_author uuid, thread_visibility text, thread_deleted_at timestamp with time zone, thread_state text, category_deleted_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
