    AS $$
SELECT * FROM api.forum_thread_placement_v1(p_source_id);
$$;


--
-- Name: forum_thread_redirect_v1(uuid, uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_thread_redirect_v1(p_actor uuid, p_thread_id uuid) RETURNS TABLE(target_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
WITH RECURSIVE chain(id,depth) AS (
    SELECT p_thread_id,0 UNION ALL
    SELECT x.target_id,c.depth+1 FROM chain c JOIN public.thread_transfers x ON x.source_id = c.id
    WHERE x.operation = 'merge' AND x.undone_at IS NULL AND c.depth < 16
)
SELECT c.id FROM chain c WHERE c.depth > 0 AND api.core_product_read_thread_v1(p_actor,c.id)
ORDER BY c.depth DESC LIMIT 1
$$;


--
-- Name: forum_thread_redirect_v2(uuid, uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_thread_redirect_v2(p_actor uuid, p_thread_id uuid) RETURNS TABLE(target_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.forum_thread_redirect_v1(p_actor, p_thread_id);
$$;


