-- Name: forum_thread_tags_v1(uuid[]); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_thread_tags_v1(p_thread_ids uuid[]) RETURNS TABLE(thread_id uuid, slug text, name text, tag_position smallint)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT tt.thread_id, t.slug, t.name, tt.position
FROM public.thread_tags tt
JOIN public.tags t ON t.tag_id = tt.tag_id
WHERE tt.thread_id = ANY(p_thread_ids)
ORDER BY tt.thread_id, tt.position
$$;


