CREATE FUNCTION api.forum_write_command_v4(p_log jsonb, p_answer jsonb, p_store_type text, p_command jsonb, p_record jsonb, p_draft_id uuid, p_draft_revision bigint) RETURNS TABLE(outcome text, response json, stored json)
