--
-- Name: forum_write_command_v5(jsonb, jsonb, text, jsonb, jsonb, uuid, bigint); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.forum_write_command_v5(p_log jsonb, p_answer jsonb, p_store_type text, p_command jsonb, p_record jsonb, p_draft_id uuid, p_draft_revision bigint) RETURNS TABLE(outcome text, response json, stored json)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE result record;
BEGIN
    SELECT * INTO result FROM api.forum_write_command_v4(p_log, p_answer, p_store_type, p_command, p_record, p_draft_id, p_draft_revision);
    PERFORM api.core_forum_attach_signature_v1(result.stored::jsonb, p_command);
    RETURN QUERY SELECT result.outcome, result.response, result.stored;
END
$$;


