-- Name: identity_profile_replies_v2(uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.identity_profile_replies_v2(p_user_id uuid, p_after_at timestamp with time zone, p_after_id uuid, p_row_limit integer) RETURNS TABLE(post_id uuid, thread_id uuid, author_user_id uuid, "position" bigint, visibility text, moderation_state text, created_at timestamp with time zone, thread_title text, thread_slug text, body text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
