-- Name: identity_register_command_v4(jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, text, jsonb, jsonb, jsonb, jsonb, text, jsonb, text); Type: FUNCTION; Schema: api; Owner: -
--

