CREATE FUNCTION api.identity_revoke_passwords_v1(p_ids jsonb, p_revoked_at timestamp with time zone) RETURNS TABLE(updated integer)
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
