CREATE FUNCTION api.identity_rotate_token_v1(p_token_id uuid, p_values jsonb) RETURNS SETOF api.identity_token_v1
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
