-- Name: identity_second_factor_cancel_v1(uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.identity_second_factor_cancel_v1(p_user_id uuid) RETURNS TABLE(status text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    DELETE FROM public.second_factors f
        WHERE f.user_id = p_user_id AND f.state = 'pending';
    RETURN QUERY SELECT CASE WHEN FOUND THEN 'ok' ELSE 'not_found' END;
END;
$$;


