CREATE FUNCTION api.identity_second_factor_challenge_v1(p_token_hash text, p_now timestamp with time zone) RETURNS TABLE(user_id uuid, open boolean, secret_sealed text, key_id text, last_step bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
