CREATE FUNCTION api.moderation_automod_settings_set_v2(p_link_limit integer, p_link_trust_below integer, p_link_action text, p_actor_user_id uuid, p_now timestamp with time zone, p_audit jsonb) RETURNS TABLE(status text)
