CREATE FUNCTION api.moderation_can_participate_v2(p_user_id uuid, p_now text) RETURNS TABLE(ok integer, reason text, suspension_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
