-- Name: moderation_member_notes_for_reports_v2(uuid[], integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.moderation_member_notes_for_reports_v2(p_report_ids uuid[], p_per_member integer) RETURNS TABLE(report_id uuid, subject_user_id uuid, subject_username text, note_total bigint, note_id uuid, author_username text, body text, created_at timestamp with time zone, updated_at timestamp with time zone, updated_by_username text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.moderation_member_notes_for_reports_v1(p_report_ids,
    p_per_member);
$$;


--
-- Name: moderation_member_notes_v1(uuid, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.moderation_member_notes_v1(p_subject_user_id uuid, p_row_limit integer) RETURNS TABLE(note_id uuid, subject_user_id uuid, author_user_id uuid, author_username text, body text, created_at timestamp with time zone, updated_at timestamp with time zone, updated_by_user_id uuid, updated_by_username text, note_total bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT n.note_id, n.subject_user_id, n.author_user_id, a.username, n.body,
    n.created_at, n.updated_at, n.updated_by_user_id, e.username,
    count(*) OVER ()
FROM public.member_notes n
LEFT JOIN public.users a ON a.id = n.author_user_id
LEFT JOIN public.users e ON e.id = n.updated_by_user_id
WHERE n.subject_user_id = p_subject_user_id
ORDER BY n.created_at DESC, n.note_id DESC
LIMIT p_row_limit
$$;


