CREATE FUNCTION api.moderation_review_mine_v4(p_user_id uuid, p_row_limit integer, p_member boolean, p_global_read boolean, p_category_ids uuid[], p_space_ids uuid[]) RETURNS TABLE(review_id uuid, kind text, category_id uuid, category_title text, thread_id uuid, thread_title text, title text, body_rendered_safe text, status text, decision_reason text, post_id uuid, created_at timestamp with time zone, decided_at timestamp with time zone)
