CREATE FUNCTION api.moderation_thread_transfer_v2(p_actor uuid, p_command uuid, p_source_id uuid, p_target_id uuid, p_operation text, p_post_numbers bigint[], p_title text, p_reason text) RETURNS TABLE(result jsonb)
