CREATE FUNCTION api.moderation_watched_word_add_v2(p_word_id uuid, p_phrase text, p_action text, p_replacement text, p_actor_user_id uuid, p_now timestamp with time zone, p_audit jsonb) RETURNS TABLE(status text, word_id uuid)
    LANGUAGE sql SECURITY DEFINER
