-- Name: notification_delivery_plan_v4(uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_delivery_plan_v4(p_user_id uuid, p_notification_type text) RETURNS TABLE(event_type text, in_app boolean, email boolean, email_address text, locale text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.notification_delivery_plan_v3(p_user_id,
    p_notification_type);
$$;


--
-- Name: notification_digest_claim_v1(uuid, text, timestamp with time zone, uuid, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_digest_claim_v1(p_user_id uuid, p_frequency text, p_period_start timestamp with time zone, p_event_id uuid, p_now timestamp with time zone) RETURNS TABLE(status text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE
    held timestamptz;
BEGIN
    IF p_user_id IS NULL OR p_frequency IS NULL OR p_period_start IS NULL
        OR p_event_id IS NULL OR p_now IS NULL THEN
        RETURN QUERY SELECT 'invalid'::text;
        RETURN;
    END IF;
    SELECT g.sent_at INTO held FROM public.notification_digests g
        WHERE g.user_id = p_user_id AND g.frequency = p_frequency
            AND g.period_start = p_period_start
            AND g.event_id = p_event_id
        FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'missing'::text;
        RETURN;
    END IF;
    IF held IS NOT NULL THEN
        RETURN QUERY SELECT 'sent'::text;
        RETURN;
    END IF;
    UPDATE public.notification_digests g SET sent_at = p_now
        WHERE g.user_id = p_user_id AND g.frequency = p_frequency
            AND g.period_start = p_period_start;
    RETURN QUERY SELECT 'claimed'::text;
END;
$$;


