--

CREATE FUNCTION api.notification_digest_due_v4(p_now timestamp with time zone, p_after_start timestamp with time zone, p_after_user_id uuid, p_row_limit integer) RETURNS TABLE(user_id uuid, frequency text, period_start timestamp with time zone, period_end timestamp with time zone)
