CREATE FUNCTION api.notification_digest_items_v4(p_user_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_member boolean, p_global_read boolean, p_category_ids uuid[], p_space_ids uuid[], p_row_limit integer) RETURNS TABLE(thread_id uuid, title text, category_title text, new_posts integer, first_unread_position bigint, last_post_at timestamp with time zone, thread_total integer)
