--
-- Name: notification_digest_record_v1(uuid, text, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, jsonb, text, jsonb, boolean); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_digest_record_v1(p_user_id uuid, p_frequency text, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_thread_count integer, p_now timestamp with time zone, p_event jsonb, p_outbox_id text, p_outbox_extras jsonb, p_explicit boolean) RETURNS TABLE(status text, event_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $_$
DECLARE
    amount integer;
    queued_id uuid;
BEGIN
    IF p_user_id IS NULL OR p_now IS NULL
        OR coalesce(p_frequency, '') NOT IN ('daily', 'weekly')
        OR p_period_start IS NULL OR p_period_end IS NULL
        OR p_period_end <= p_period_start
        OR coalesce(p_thread_count, -1) < 0
        OR (p_thread_count > 0) <> (p_event IS NOT NULL)
        OR (p_event IS NOT NULL
            AND coalesce(p_event ->> 'event_id', '') !~
                '^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$') THEN
        RETURN QUERY SELECT 'invalid'::text, NULL::uuid;
        RETURN;
    END IF;
    queued_id := (p_event ->> 'event_id')::uuid;
    INSERT INTO public.notification_digests (user_id, frequency,
        period_start, period_end, status, thread_count, event_id,
        created_at)
    VALUES (p_user_id, p_frequency, p_period_start, p_period_end,
        CASE WHEN queued_id IS NULL THEN 'empty' ELSE 'queued' END,
        p_thread_count, queued_id, p_now)
    ON CONFLICT ON CONSTRAINT notification_digests_pkey DO NOTHING;
    GET DIAGNOSTICS amount = ROW_COUNT;
    IF amount = 0 THEN
        RETURN QUERY SELECT 'duplicate'::text, NULL::uuid;
        RETURN;
    END IF;
    IF queued_id IS NULL THEN
        RETURN QUERY SELECT 'empty'::text, NULL::uuid;
        RETURN;
    END IF;
    PERFORM api.ops_record_event_v1(p_event, p_outbox_id, p_outbox_extras,
        coalesce(p_explicit, false));
    RETURN QUERY SELECT 'queued'::text, queued_id;
END;
$_$;


--
-- Name: notification_digest_record_v3(uuid, text, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, jsonb, text, jsonb, boolean); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_digest_record_v3(p_user_id uuid, p_frequency text, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_thread_count integer, p_now timestamp with time zone, p_event jsonb, p_outbox_id text, p_outbox_extras jsonb, p_explicit boolean) RETURNS TABLE(status text, event_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    IF p_user_id IS NOT NULL AND p_period_start IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(2026101701,
            hashtext(p_user_id::text));
        IF EXISTS (SELECT 1 FROM public.notification_digests g
            WHERE g.user_id = p_user_id
                AND g.period_end > p_period_start) THEN
            RETURN QUERY SELECT 'duplicate'::text, NULL::uuid;
            RETURN;
        END IF;
    END IF;
    RETURN QUERY SELECT * FROM api.notification_digest_record_v1(p_user_id,
        p_frequency, p_period_start, p_period_end, p_thread_count, p_now,
        p_event, p_outbox_id, p_outbox_extras, p_explicit);
END;
$$;


