--
-- Name: notification_digest_release_v1(uuid, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_digest_release_v1(p_user_id uuid, p_frequency text, p_period_start timestamp with time zone, p_event_id uuid) RETURNS TABLE(status text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    UPDATE public.notification_digests g SET sent_at = NULL
        WHERE g.user_id = p_user_id AND g.frequency = p_frequency
            AND g.period_start = p_period_start
            AND g.event_id = p_event_id AND g.sent_at IS NOT NULL;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'unchanged'::text;
        RETURN;
    END IF;
    RETURN QUERY SELECT 'released'::text;
END;
$$;


