--
-- Name: notification_digest_unsubscribe_v1(uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_digest_unsubscribe_v1(p_user_id uuid, p_now timestamp with time zone, p_audit jsonb) RETURNS TABLE(status text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    IF p_user_id IS NULL OR p_now IS NULL OR p_audit IS NULL THEN
        RETURN QUERY SELECT 'invalid'::text;
        RETURN;
    END IF;
    PERFORM 1 FROM public.users u
        WHERE u.id = p_user_id AND u.deleted_at IS NULL
        FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'not_found'::text;
        RETURN;
    END IF;
    UPDATE public.notification_preferences p
        SET enabled = false, updated_at = p_now
        WHERE p.user_id = p_user_id AND p.channel = 'digest' AND p.enabled;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'unchanged'::text;
        RETURN;
    END IF;
    PERFORM api.ops_record_audit_v1(p_audit, false);
    RETURN QUERY SELECT 'ok'::text;
END;
$$;


