    p_audit);
$$;


--
-- Name: notification_fanout_candidates_v1(text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_fanout_candidates_v1(p_target_type text, p_target_id uuid, p_notification_type text, p_actor_id uuid, p_excluded_user_id uuid) RETURNS TABLE(user_id uuid, in_app boolean, email boolean, email_address text, locale text, event_type text, silenced boolean, status text, suspended boolean, grants json, moderates boolean, listed uuid[], trust_level integer)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT s.user_id,
    coalesce(plan.in_app, true),
    coalesce(plan.email, false),
    plan.email_address,
    plan.locale,
    plan.event_type,
    p_actor_id IS NOT NULL AND s.user_id <> p_actor_id AND EXISTS (
        SELECT 1 FROM api.community_relation_between_v1(s.user_id, p_actor_id)),
    viewer.status,
    viewer.suspended,
    viewer.grants,
    viewer.moderates,
    viewer.listed,
    viewer.trust_level
FROM api.notification_subscribers_v3(p_target_type, p_target_id, p_notification_type) s
LEFT JOIN LATERAL api.notification_delivery_plan_v3(s.user_id, p_notification_type) plan
    ON true
LEFT JOIN LATERAL api.forum_resolve_viewer_v7(s.user_id) viewer ON true
WHERE p_excluded_user_id IS NULL OR s.user_id <> p_excluded_user_id
ORDER BY s.user_id
$$;


