-- Name: notification_fanout_deliver_v2(jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_fanout_deliver_v2(p_recipients jsonb) RETURNS TABLE(recipient_user_id uuid, outcome text, result jsonb, unread_count bigint, email_queued boolean, error text)
