--
-- Name: notification_subscribers_v1(text, uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_subscribers_v1(p_target_type text, p_target_id uuid, p_notification_type text) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT s.user_id FROM public.subscriptions s WHERE s.target_type = p_target_type AND s.target_id = p_target_id AND s.revoked_at IS NULL AND s.muted_at IS NULL AND s.preference <> 'none' AND (s.preference = 'all' OR p_notification_type = 'mention')
$$;


--
-- Name: notification_subscribers_v2(text, uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_subscribers_v2(p_target_type text, p_target_id uuid, p_notification_type text) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.notification_subscribers_v1(p_target_type, p_target_id, p_notification_type);
$$;


--
-- Name: notification_subscribers_v3(text, uuid, text); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.notification_subscribers_v3(p_target_type text, p_target_id uuid, p_notification_type text) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT d.user_id FROM api.notification_subscribers_v1(p_target_type,p_target_id,p_notification_type) d
UNION
SELECT s.user_id FROM public.threads t JOIN public.subscriptions s
    ON s.target_type = 'category' AND s.target_id = t.category_id
WHERE p_target_type = 'thread' AND t.thread_id = p_target_id
    AND s.revoked_at IS NULL AND s.muted_at IS NULL AND s.preference <> 'none'
    AND (s.preference = 'all' OR p_notification_type = 'mention')
    AND NOT EXISTS(SELECT 1 FROM public.subscriptions mute WHERE mute.user_id = s.user_id
        AND mute.target_type = 'thread' AND mute.target_id = p_target_id
        AND mute.revoked_at IS NULL AND mute.muted_at IS NOT NULL)
$$;


