CREATE FUNCTION api.notification_unread_count_v8(p_recipient_user_id uuid, p_filter_sources boolean, p_member boolean, p_global_read boolean, p_viewer_user_id uuid, p_category_ids uuid[], p_space_ids uuid[]) RETURNS TABLE(unread_count bigint)
