CREATE FUNCTION api.ops_outbox_metrics_v1(p_now timestamp with time zone) RETURNS TABLE(pending bigint, failed bigint, retry_backlog bigint, dead_letters bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
