$$;


--
-- Name: ops_rate_limit_check_v1(text, text, text, timestamp with time zone, integer, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.ops_rate_limit_check_v1(p_scope text, p_actor_hash text, p_action text, p_window_start timestamp with time zone, p_window_seconds integer, p_limit integer, p_now timestamp with time zone, p_expires_at timestamp with time zone) RETURNS TABLE(scope text, actor_hash text, action text, window_started_at timestamp with time zone, observed_count integer, blocked_count integer)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    RETURN QUERY
    INSERT INTO public.rate_limit_buckets AS b (
        scope, actor_hash, action, window_started_at, window_seconds,
        observed_count, blocked_count, first_seen_at, last_seen_at, expires_at)
    VALUES (p_scope, p_actor_hash, p_action, p_window_start, p_window_seconds,
        1, CASE WHEN 1 > p_limit THEN 1 ELSE 0 END, p_now, p_now, p_expires_at)
    ON CONFLICT ON CONSTRAINT rate_limit_buckets_pkey DO UPDATE SET
        observed_count = b.observed_count + 1,
        blocked_count = b.blocked_count
            + CASE WHEN b.observed_count + 1 > p_limit THEN 1 ELSE 0 END,
        last_seen_at = EXCLUDED.last_seen_at,
        expires_at = EXCLUDED.expires_at
    RETURNING b.scope, b.actor_hash, b.action, b.window_started_at,
        b.observed_count, b.blocked_count;
END;
$$;


