--
-- Name: ops_retention_purge_v1(text, timestamp with time zone, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.ops_retention_purge_v1(p_source text, p_cutoff timestamp with time zone, p_row_limit integer) RETURNS TABLE(deleted bigint, ok integer)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
BEGIN
    CASE p_source
    WHEN 'Session' THEN
      RETURN QUERY WITH picked AS (
        SELECT a.tableoid AS oid, a.ctid AS tid FROM public.sessions a WHERE a.expires_at <= p_cutoff OR a.revoked_at IS NOT NULL
        ORDER BY a.expires_at ASC LIMIT p_row_limit FOR UPDATE SKIP LOCKED
      ), removed AS (
        DELETE FROM public.sessions a USING picked b WHERE a.tableoid = b.oid AND a.ctid = b.tid RETURNING 1
      ) SELECT count(*), 1 FROM removed;
    WHEN 'IdentityToken' THEN
      RETURN QUERY WITH picked AS (
        SELECT a.tableoid AS oid, a.ctid AS tid FROM public.identity_tokens a WHERE a.expires_at <= p_cutoff OR a.used_at IS NOT NULL
        ORDER BY a.expires_at ASC LIMIT p_row_limit FOR UPDATE SKIP LOCKED
      ), removed AS (
        DELETE FROM public.identity_tokens a USING picked b WHERE a.tableoid = b.oid AND a.ctid = b.tid RETURNING 1
      ) SELECT count(*), 1 FROM removed;
    WHEN 'RateLimitBucket' THEN
      RETURN QUERY WITH picked AS (
        SELECT a.tableoid AS oid, a.ctid AS tid FROM public.rate_limit_buckets a WHERE a.expires_at <= p_cutoff
        ORDER BY a.expires_at ASC LIMIT p_row_limit FOR UPDATE SKIP LOCKED
      ), removed AS (
        DELETE FROM public.rate_limit_buckets a USING picked b WHERE a.tableoid = b.oid AND a.ctid = b.tid RETURNING 1
      ) SELECT count(*), 1 FROM removed;
    WHEN 'OutboxMessage' THEN
      RETURN QUERY WITH picked AS (
        SELECT a.tableoid AS oid, a.ctid AS tid FROM public.outbox_messages a WHERE a.created_at <= p_cutoff AND a.status IN ('done','cancelled')
        ORDER BY a.created_at ASC LIMIT p_row_limit FOR UPDATE SKIP LOCKED
      ), removed AS (
        DELETE FROM public.outbox_messages a USING picked b WHERE a.tableoid = b.oid AND a.ctid = b.tid RETURNING 1
      ) SELECT count(*), 1 FROM removed;
    WHEN 'DeadLetter' THEN
      RETURN QUERY WITH picked AS (
        SELECT a.tableoid AS oid, a.ctid AS tid FROM public.dead_letters a WHERE a.last_failed_at <= p_cutoff
        ORDER BY a.last_failed_at ASC LIMIT p_row_limit FOR UPDATE SKIP LOCKED
      ), removed AS (
        DELETE FROM public.dead_letters a USING picked b WHERE a.tableoid = b.oid AND a.ctid = b.tid RETURNING 1
      ) SELECT count(*), 1 FROM removed;
    ELSE RAISE EXCEPTION 'unknown retention source';
    END CASE;
END;
$$;


--
-- Name: ops_retention_purge_v2(text, timestamp with time zone, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.ops_retention_purge_v2(p_source text, p_cutoff timestamp with time zone, p_row_limit integer) RETURNS TABLE(deleted bigint, ok integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.ops_retention_purge_v1(p_source, p_cutoff, p_row_limit);
$$;


--
-- Name: ops_retention_purge_v3(text, timestamp with time zone, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.ops_retention_purge_v3(p_source text, p_cutoff timestamp with time zone, p_row_limit integer) RETURNS TABLE(deleted bigint, ok integer)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE previous record; invitations bigint := 0;
BEGIN
    SELECT * INTO previous FROM api.ops_retention_purge_v1(p_source,p_cutoff,p_row_limit);
    IF p_source = 'IdentityToken' AND previous.deleted < p_row_limit THEN
        WITH picked AS (SELECT i.invitation_id FROM public.registration_invitations i WHERE i.expires_at <= p_cutoff
            ORDER BY i.expires_at,i.invitation_id LIMIT greatest(p_row_limit-previous.deleted,0) FOR UPDATE SKIP LOCKED),
        removed AS (DELETE FROM public.registration_invitations i USING picked x WHERE i.invitation_id = x.invitation_id RETURNING 1)
        SELECT count(*) INTO invitations FROM removed;
    END IF;
    RETURN QUERY SELECT previous.deleted+invitations,previous.ok;
END;
$$;


--
-- Name: ops_retention_purge_v4(text, timestamp with time zone, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.ops_retention_purge_v4(p_source text, p_cutoff timestamp with time zone, p_row_limit integer) RETURNS TABLE(deleted bigint, ok integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.ops_retention_purge_v3(p_source, p_cutoff, p_row_limit);
$$;


