-- Name: outbox_owned_write_v2(uuid, text, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.outbox_owned_write_v2(p_outbox_id uuid, p_worker_id text, p_changes jsonb) RETURNS TABLE(landed boolean)
