-- Name: privacy_insert_v2(text, jsonb); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.privacy_insert_v2(p_source text, p_row jsonb) RETURNS TABLE(document json)
    LANGUAGE sql SECURITY DEFINER
