    amount bigint;
BEGIN
    IF p_source = 'PostReaction' THEN
        DELETE FROM public.post_reactions r WHERE r.user_id = p_user_id;
        GET DIAGNOSTICS amount = ROW_COUNT;
        RETURN QUERY SELECT amount;
