    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.search_remove_document_v1(p_entity_type, p_entity_id);
$$;


--
-- Name: search_remove_post_batch_v1(uuid, uuid[]); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.search_remove_post_batch_v1(p_thread_id uuid, p_post_ids uuid[]) RETURNS TABLE(removed bigint)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE v_deleted bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(k.lock_key, 0)) FROM (SELECT 'search_document:post:' || u::text AS lock_key FROM unnest(p_post_ids) u ORDER BY lock_key) k;
  IF EXISTS (SELECT 1 FROM public.threads t WHERE t.thread_id = p_thread_id AND t.deleted_at IS NULL AND t.moderation_state IN ('visible','locked')) THEN RETURN QUERY SELECT NULL::bigint; RETURN; END IF;
  DELETE FROM public.search_documents d WHERE d.entity_type = 'post' AND d.entity_id = ANY(p_post_ids);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN QUERY SELECT v_deleted;
END;
$$;


--
-- Name: search_remove_post_batch_v2(uuid, uuid[]); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.search_remove_post_batch_v2(p_thread_id uuid, p_post_ids uuid[]) RETURNS TABLE(removed bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.search_remove_post_batch_v1(p_thread_id, p_post_ids);
$$;


