--
-- Name: session_create_v1(uuid, uuid, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text, boolean); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.session_create_v1(p_session_id uuid, p_user_id uuid, p_session_hash text, p_created_at timestamp with time zone, p_last_seen_at timestamp with time zone, p_expires_at timestamp with time zone, p_revoked_at timestamp with time zone, p_ip_hash text, p_user_agent_hash text, p_retry boolean) RETURNS TABLE(result_code text, session_id uuid, user_id uuid, session_hash text, created_at timestamp with time zone, last_seen_at timestamp with time zone, expires_at timestamp with time zone, revoked_at timestamp with time zone, ip_hash text, user_agent_hash text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE
    v_session public.sessions%ROWTYPE;
    v_constraint text;
BEGIN
    BEGIN
        INSERT INTO public.sessions (session_id, user_id, session_hash,
            created_at, last_seen_at, expires_at, revoked_at, ip_hash,
            user_agent_hash)
        VALUES (p_session_id, p_user_id, p_session_hash, p_created_at,
            p_last_seen_at, p_expires_at, p_revoked_at, p_ip_hash,
            p_user_agent_hash)
        RETURNING * INTO v_session;
    EXCEPTION WHEN unique_violation THEN
        IF p_retry THEN
            RAISE;
        END IF;
        GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
        IF v_constraint = 'sessions_pkey' THEN
            SELECT s.* INTO v_session FROM public.sessions s
                WHERE s.session_id = p_session_id;
            IF FOUND AND v_session.user_id = p_user_id
                AND v_session.session_hash = p_session_hash THEN
                RETURN QUERY SELECT 'skipped'::text, v_session.*;
            ELSE
                RETURN QUERY SELECT 'retry_id'::text, v_session.*;
            END IF;
        ELSE
            RETURN QUERY SELECT 'retry_token'::text, v_session.*;
        END IF;
        RETURN;
    END;
    RETURN QUERY SELECT 'ok'::text, v_session.*;
END;
$$;


