CREATE FUNCTION api.session_live_v1(p_session_ids uuid[], p_now timestamp with time zone) RETURNS TABLE(session_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
