--
-- Name: session_lookup_v1(uuid, uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.session_lookup_v1(p_session_id uuid, p_user_id uuid) RETURNS SETOF api.identity_session_v1
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
    IF p_user_id IS NULL THEN
        RETURN QUERY SELECT s.session_id, s.user_id, s.session_hash,
            s.created_at, s.last_seen_at, s.expires_at, s.revoked_at,
            s.ip_hash, s.user_agent_hash FROM public.sessions s
            WHERE s.session_id = p_session_id;
    ELSE
        RETURN QUERY SELECT s.session_id, s.user_id, s.session_hash,
            s.created_at, s.last_seen_at, s.expires_at, s.revoked_at,
            s.ip_hash, s.user_agent_hash FROM public.sessions s
            WHERE s.session_id = p_session_id AND s.user_id = p_user_id;
    END IF;
END;
$$;


