--
-- Name: session_revoke_user_v1(uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.session_revoke_user_v1(p_user_id uuid, p_revoked_at timestamp with time zone, p_keep_session_id uuid) RETURNS TABLE(revoked_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE
    v_updated bigint;
BEGIN
    IF p_keep_session_id IS NULL THEN
        UPDATE public.sessions s
            SET revoked_at = greatest(p_revoked_at, s.created_at)
            WHERE s.user_id = p_user_id AND s.revoked_at IS NULL;
    ELSE
        UPDATE public.sessions s
            SET revoked_at = greatest(p_revoked_at, s.created_at)
            WHERE s.user_id = p_user_id AND s.revoked_at IS NULL
                AND s.session_id <> p_keep_session_id;
    END IF;
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN QUERY SELECT v_updated;
END;
$$;


