    AS $$
SELECT * FROM api.session_revoke_user_v1(p_user_id, p_revoked_at, p_keep_session_id);
$$;


--
-- Name: session_revoke_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.session_revoke_v1(p_session_id uuid, p_user_id uuid, p_revoked_at timestamp with time zone) RETURNS TABLE(result_code text, session_id uuid, user_id uuid, session_hash text, created_at timestamp with time zone, last_seen_at timestamp with time zone, expires_at timestamp with time zone, revoked_at timestamp with time zone, ip_hash text, user_agent_hash text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE
    v_session public.sessions%ROWTYPE;
    v_updated bigint;
BEGIN
    IF p_user_id IS NULL THEN
        SELECT s.* INTO v_session FROM public.sessions s
            WHERE s.session_id = p_session_id;
    ELSE
        SELECT s.* INTO v_session FROM public.sessions s
            WHERE s.session_id = p_session_id AND s.user_id = p_user_id;
    END IF;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'not_found'::text, v_session.*;
        RETURN;
    END IF;
    IF v_session.revoked_at IS NOT NULL THEN
        RETURN QUERY SELECT 'skipped'::text, v_session.*;
        RETURN;
    END IF;
    UPDATE public.sessions s
        SET revoked_at = greatest(p_revoked_at, s.created_at)
        WHERE s.session_id = p_session_id AND s.revoked_at IS NULL;
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    -- The old store returns the row read before its conditional UPDATE.
    RETURN QUERY SELECT CASE WHEN v_updated = 0 THEN 'skipped' ELSE 'ok' END,
        v_session.*;
END;
$$;


