SELECT * FROM api.session_revoke_v1(p_session_id, p_user_id, p_revoked_at);
$$;


--
-- Name: session_validate_v1(uuid, uuid, text, timestamp with time zone, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.session_validate_v1(p_session_id uuid, p_user_id uuid, p_token_hash text, p_now timestamp with time zone, p_touch_interval_seconds integer) RETURNS TABLE(result_code text, session_id uuid, user_id uuid, session_hash text, created_at timestamp with time zone, last_seen_at timestamp with time zone, expires_at timestamp with time zone, revoked_at timestamp with time zone, ip_hash text, user_agent_hash text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
DECLARE
    v_session public.sessions%ROWTYPE;
BEGIN
    SELECT s.* INTO v_session FROM public.sessions s
        WHERE s.session_id = p_session_id AND s.user_id = p_user_id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'not_found'::text, v_session.*;
        RETURN;
    END IF;
    IF NOT api.core_session_digest_equals_v1(v_session.session_hash,
        p_token_hash) THEN
        RETURN QUERY SELECT 'invalid_token'::text, v_session.*;
        RETURN;
    END IF;
    IF v_session.revoked_at IS NOT NULL THEN
        RETURN QUERY SELECT 'revoked'::text, v_session.*;
        RETURN;
    END IF;
    -- Identity::Support parses timestamps to whole seconds, discarding the
    -- fractions. Keep the same boundary at expiry and at the touch interval.
    IF date_trunc('second', v_session.expires_at) <= p_now THEN
        UPDATE public.sessions s SET revoked_at = p_now
            WHERE s.session_id = p_session_id;
        v_session.revoked_at := p_now;
        RETURN QUERY SELECT 'expired'::text, v_session.*;
        RETURN;
    END IF;
    IF extract(epoch FROM p_now - date_trunc('second', v_session.last_seen_at))
        >= p_touch_interval_seconds THEN
        UPDATE public.sessions s SET last_seen_at = p_now
            WHERE s.session_id = p_session_id;
        v_session.last_seen_at := p_now;
    END IF;
    RETURN QUERY SELECT 'ok'::text, v_session.*;
END;
$$;


--
-- Name: session_validate_v2(uuid, uuid, text, timestamp with time zone, integer); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION api.session_validate_v2(p_session_id uuid, p_user_id uuid, p_token_hash text, p_now timestamp with time zone, p_touch_interval_seconds integer) RETURNS TABLE(result_code text, session_id uuid, user_id uuid, session_hash text, created_at timestamp with time zone, last_seen_at timestamp with time zone, expires_at timestamp with time zone, revoked_at timestamp with time zone, ip_hash text, user_agent_hash text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
SELECT * FROM api.session_validate_v1(p_session_id, p_user_id, p_token_hash, p_now, p_touch_interval_seconds);
$$;


