-- Name: notification_type_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_type_preferences (
    user_id uuid NOT NULL,
    event_type text NOT NULL,
    channel text NOT NULL,
    enabled boolean NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT notification_type_preferences_channel_check CHECK ((channel = ANY (ARRAY['in_app'::text, 'email'::text]))),
    CONSTRAINT notification_type_preferences_event_type_check CHECK ((event_type = ANY (ARRAY['reply'::text, 'mention'::text, 'moderation'::text, 'message'::text])))
);


--
-- Name: TABLE notification_type_preferences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notification_type_preferences IS 'A member''s switch for each kind of notification on each channel; a kind with no row has its default.';


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    notification_id uuid NOT NULL,
    recipient_user_id uuid NOT NULL,
    source_type text NOT NULL,
    source_id uuid,
    notification_type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
)
PARTITION BY RANGE (created_at);


--
-- Name: TABLE notifications; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notifications IS 'A notification for a member, append-only, partitioned by month on created_at.';


--
-- Name: notifications_default; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications_default (
    notification_id uuid CONSTRAINT notifications_notification_id_not_null NOT NULL,
    recipient_user_id uuid CONSTRAINT notifications_recipient_user_id_not_null NOT NULL,
    source_type text CONSTRAINT notifications_source_type_not_null NOT NULL,
    source_id uuid,
    notification_type text CONSTRAINT notifications_notification_type_not_null NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb CONSTRAINT notifications_payload_not_null NOT NULL,
    created_at timestamp with time zone DEFAULT now() CONSTRAINT notifications_created_at_not_null NOT NULL
);


--
-- Name: outbox_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outbox_messages (
    outbox_id uuid NOT NULL,
    event_id uuid NOT NULL,
    queue text NOT NULL,
    job_type text NOT NULL,
    idempotency_key text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    last_error text,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_by text,
    locked_until timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_error_class text,
    failure_type text,
    CONSTRAINT outbox_messages_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT outbox_messages_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT outbox_messages_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'done'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: TABLE outbox_messages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outbox_messages IS 'The jobs and notifications an event queues, delivered at least once by the workers.';


--
-- Name: partition_registry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.partition_registry (
    table_name text NOT NULL,
    partition_name text NOT NULL,
    range_start timestamp with time zone NOT NULL,
    range_end timestamp with time zone NOT NULL,
    state text DEFAULT 'planned'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    detached_at timestamp with time zone,
    archived_at timestamp with time zone,
    CONSTRAINT partition_registry_range_check CHECK ((range_end > range_start)),
    CONSTRAINT partition_registry_state_check CHECK ((state = ANY (ARRAY['planned'::text, 'created'::text, 'detached'::text, 'archived'::text, 'dropped'::text])))
);


--
-- Name: TABLE partition_registry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.partition_registry IS 'The monthly partitions of the append-only logs, as the partition window made them.';


--
-- Name: permissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.permissions (
    permission_id uuid NOT NULL,
    name text NOT NULL,
    resource_type text NOT NULL,
    action text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE permissions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.permissions IS 'An action on a kind of resource, by name.';


--
-- Name: poll_ballots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.poll_ballots (
    thread_id uuid NOT NULL,
    user_id uuid NOT NULL,
    option_number integer NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE poll_ballots; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.poll_ballots IS 'One mutable single-choice ballot per member and poll, never exposed in aggregate results.';


--
-- Name: poll_options; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.poll_options (
    thread_id uuid NOT NULL,
    option_number integer NOT NULL,
    label text NOT NULL,
    votes bigint DEFAULT 0 NOT NULL,
    CONSTRAINT poll_options_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 120))),
    CONSTRAINT poll_options_option_number_check CHECK (((option_number >= 1) AND (option_number <= 10))),
    CONSTRAINT poll_options_votes_check CHECK ((votes >= 0))
);


--
-- Name: TABLE poll_options; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.poll_options IS 'Immutable ordered poll options with transactionally maintained vote counts.';


--
-- Name: post_bodies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_bodies (
    body_id uuid NOT NULL,
    post_id uuid NOT NULL,
    body_format text DEFAULT 'markdown'::text NOT NULL,
    body_source text NOT NULL,
    body_rendered_safe text NOT NULL,
    source_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT post_bodies_body_format_check CHECK ((body_format = ANY (ARRAY['markdown'::text, 'plain'::text]))),
    CONSTRAINT post_bodies_body_source_length_check CHECK ((char_length(body_source) <= 50000))
);


--
-- Name: TABLE post_bodies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.post_bodies IS 'The text of a post, as written and as rendered safe; each edit adds a body.';


--
-- Name: post_likes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_likes (
    post_id uuid NOT NULL,
    user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE post_likes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.post_likes IS 'A member''s like on a post, at most one; never on their own post.';


--
-- Name: post_reactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_reactions (
    post_id uuid NOT NULL,
    user_id uuid NOT NULL,
    reaction text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT post_reactions_reaction_check CHECK ((reaction = ANY (ARRAY['heart'::text, 'laugh'::text, 'celebrate'::text, 'think'::text])))
);


--
-- Name: TABLE post_reactions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.post_reactions IS 'A member''s reactions on a post, one of four kinds each at most once; never on their own post.';


--
-- Name: post_replies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_replies (
    post_id uuid NOT NULL,
    reply_to_post_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT post_replies_not_self_check CHECK ((post_id <> reply_to_post_id))
);


--
-- Name: TABLE post_replies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.post_replies IS 'The post a reply answers, when it answers one: both posts in the same thread.';


--
-- Name: post_revisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_revisions (
    revision_id uuid NOT NULL,
    post_id uuid NOT NULL,
    body_id uuid NOT NULL,
    editor_user_id uuid NOT NULL,
    revision_number integer NOT NULL,
    edit_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT post_revisions_revision_number_check CHECK ((revision_number > 0))
);


--
-- Name: TABLE post_revisions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.post_revisions IS 'Each version of a post: which body, who edited it and why.';


--
-- Name: post_signatures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_signatures (
    body_id uuid NOT NULL,
    envelope jsonb NOT NULL
);


--
-- Name: TABLE post_signatures; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.post_signatures IS 'Immutable server attestations of post body revisions; trust anchors are archived separately from the database.';


--
-- Name: COLUMN post_signatures.body_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_signatures.body_id IS 'Revision body covered by this attestation; erased with its source body.';


--
-- Name: COLUMN post_signatures.envelope; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.post_signatures.envelope IS 'Ed25519 signature, canonical payload digest and public JWK; existing attestations are never overwritten.';


--
-- Name: posts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.posts (
    post_id uuid NOT NULL,
    thread_id uuid NOT NULL,
    author_user_id uuid NOT NULL,
    current_body_id uuid,
    current_revision_id uuid,
    "position" bigint NOT NULL,
    visibility text DEFAULT 'public'::text NOT NULL,
    moderation_state text DEFAULT 'visible'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    visibility_version bigint DEFAULT 1 NOT NULL,
    permission_version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    hidden_at timestamp with time zone,
    locked_at timestamp with time zone,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT posts_moderation_state_check CHECK ((moderation_state = ANY (ARRAY['visible'::text, 'hidden'::text, 'locked'::text, 'deleted'::text]))),
    CONSTRAINT posts_permission_version_check CHECK ((permission_version > 0)),
    CONSTRAINT posts_version_check CHECK ((version > 0)),
    CONSTRAINT posts_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'members'::text, 'private'::text]))),
    CONSTRAINT posts_visibility_version_check CHECK ((visibility_version > 0))
);


--
-- Name: TABLE posts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.posts IS 'A post: its thread, author, position and state; its text lives in post_bodies.';


--
-- Name: projection_generations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.projection_generations (
    generation_id uuid NOT NULL,
    projection_name text NOT NULL,
    built_from_event_id uuid,
    built_from_event_created_at timestamp with time zone,
    is_active boolean DEFAULT false NOT NULL,
    status text DEFAULT 'building'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_at timestamp with time zone,
    CONSTRAINT projection_generations_status_check CHECK ((status = ANY (ARRAY['building'::text, 'ready'::text, 'active'::text, 'failed'::text, 'retired'::text])))
);


--
-- Name: TABLE projection_generations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.projection_generations IS 'The builds of a projection: at most one active per projection, and one per source event.';


--
-- Name: rate_limit_buckets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rate_limit_buckets (
    scope text NOT NULL,
    actor_hash text NOT NULL,
    action text NOT NULL,
    window_started_at timestamp with time zone NOT NULL,
    window_seconds integer NOT NULL,
    observed_count integer DEFAULT 0 NOT NULL,
    blocked_count integer DEFAULT 0 NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT rate_limit_buckets_blocked_count_check CHECK ((blocked_count >= 0)),
    CONSTRAINT rate_limit_buckets_expires_after_window_check CHECK ((expires_at > window_started_at)),
    CONSTRAINT rate_limit_buckets_observed_count_check CHECK ((observed_count >= 0)),
    CONSTRAINT rate_limit_buckets_window_seconds_check CHECK ((window_seconds > 0))
)
WITH (fillfactor='90');


--
-- Name: TABLE rate_limit_buckets; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.rate_limit_buckets IS 'Fixed-window counters of what an actor did, by scope and action.';


--
-- Name: registration_invitations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.registration_invitations (
    invitation_id uuid NOT NULL,
    token_hash text NOT NULL,
    email_normalized text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_by uuid,
    used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT registration_invitations_check CHECK ((expires_at > created_at)),
    CONSTRAINT registration_invitations_email_normalized_check CHECK (((length(email_normalized) >= 3) AND (length(email_normalized) <= 254))),
    CONSTRAINT registration_invitations_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE registration_invitations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.registration_invitations IS 'Email-bound single-use invitation hashes; raw invitation secrets are never persisted.';


--
-- Name: registration_policy; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.registration_policy (
    singleton boolean DEFAULT true NOT NULL,
    mode text DEFAULT 'open'::text NOT NULL,
    approval_required boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT registration_policy_mode_check CHECK ((mode = ANY (ARRAY['open'::text, 'invite'::text, 'closed'::text]))),
    CONSTRAINT registration_policy_singleton_check CHECK (singleton)
);


--
-- Name: TABLE registration_policy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.registration_policy IS 'Registration mode and independent staff approval policy for new accounts.';


--
-- Name: registration_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.registration_reviews (
    user_id uuid NOT NULL,
    decision text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    CONSTRAINT registration_reviews_decision_check CHECK ((decision = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: TABLE registration_reviews; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.registration_reviews IS 'Independent staff admission decisions; email verification alone cannot approve an account.';


--
-- Name: reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reports (
    report_id uuid NOT NULL,
    reporter_user_id uuid,
    target_type text NOT NULL,
    target_id uuid NOT NULL,
    reason text NOT NULL,
    details text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    assigned_moderator_user_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolution text,
    CONSTRAINT reports_resolved_after_created_check CHECK (((resolved_at IS NULL) OR (resolved_at >= created_at))),
    CONSTRAINT reports_status_check CHECK ((status = ANY (ARRAY['open'::text, 'triaged'::text, 'resolved'::text, 'rejected'::text]))),
    CONSTRAINT reports_target_type_check CHECK ((target_type = ANY (ARRAY['thread'::text, 'post'::text, 'user'::text, 'message'::text])))
);


--
-- Name: TABLE reports; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.reports IS 'A report to the staff about a thread, a post or a member.';


--
-- Name: reputation_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reputation_events (
    reputation_event_id uuid NOT NULL,
    user_id uuid NOT NULL,
    actor_id uuid,
    source_type text NOT NULL,
    source_id uuid NOT NULL,
    delta integer NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT reputation_events_reason_check CHECK ((length(reason) > 0))
);


--
-- Name: TABLE reputation_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.reputation_events IS 'The changes to a member''s reputation, one per member and source.';


--
-- Name: retention_holds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.retention_holds (
    retention_hold_id uuid NOT NULL,
    resource_type text NOT NULL,
    resource_id uuid NOT NULL,
    reason text NOT NULL,
    starts_at timestamp with time zone DEFAULT now() NOT NULL,
    ends_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT retention_holds_window_check CHECK (((ends_at IS NULL) OR (ends_at > starts_at)))
);


--
-- Name: TABLE retention_holds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.retention_holds IS 'A hold that keeps a resource from deletion while it lasts, one active per resource.';


