--

CREATE TABLE public.role_permissions (
    role_id uuid NOT NULL,
    permission_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE role_permissions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.role_permissions IS 'The permissions of each role.';


--
-- Name: roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.roles (
    role_id uuid NOT NULL,
    name text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE roles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.roles IS 'A named set of permissions.';


--
-- Name: schema_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schema_versions (
    version text NOT NULL,
    description text NOT NULL,
    checksum text NOT NULL,
    applied_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_by text DEFAULT CURRENT_USER NOT NULL,
    execution_ms integer,
    CONSTRAINT schema_versions_execution_ms_check CHECK ((execution_ms >= 0))
);


--
-- Name: TABLE schema_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.schema_versions IS 'The migrations applied to this database, one row each.';


--
-- Name: search_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.search_documents (
    search_document_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    space_id uuid,
    visibility text NOT NULL,
    permission_scope text NOT NULL,
    visibility_version bigint NOT NULL,
    permission_version bigint NOT NULL,
    language text DEFAULT 'simple'::text NOT NULL,
    title text NOT NULL,
    title_normalized text GENERATED ALWAYS AS (lower(title)) STORED NOT NULL,
    body text NOT NULL,
    search_vector tsvector NOT NULL,
    source_version bigint NOT NULL,
    indexed_at timestamp with time zone DEFAULT now() NOT NULL,
    category_id uuid,
    author_user_id uuid,
    source_created_at timestamp with time zone,
    CONSTRAINT search_documents_permission_version_check CHECK ((permission_version > 0)),
    CONSTRAINT search_documents_source_version_check CHECK ((source_version > 0)),
    CONSTRAINT search_documents_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'members'::text, 'private'::text]))),
    CONSTRAINT search_documents_visibility_version_check CHECK ((visibility_version > 0))
);


--
-- Name: TABLE search_documents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.search_documents IS 'The searchable projection of threads and posts: the text, its tsvector and what decides who may read it.';


--
