    revoked_at timestamp with time zone,
    ip_hash text,
    user_agent_hash text,
    CONSTRAINT sessions_expires_after_created_check CHECK ((expires_at > created_at)),
    CONSTRAINT sessions_revoked_after_created_check CHECK (((revoked_at IS NULL) OR (revoked_at >= created_at)))
)
WITH (fillfactor='90');


--
-- Name: TABLE sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sessions IS 'A signed-in browser: the SHA-256 of its token, never the token, and when it was last seen.';


--
-- Name: site_announcements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.site_announcements (
    announcement_id uuid NOT NULL,
    message text NOT NULL,
    tone text DEFAULT 'notice'::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    retired_by uuid,
    retired_at timestamp with time zone,
    CONSTRAINT site_announcements_message_check CHECK (((char_length(message) >= 1) AND (char_length(message) <= 500))),
    CONSTRAINT site_announcements_retired_check CHECK (((retired_at IS NULL) = (retired_by IS NULL))),
    CONSTRAINT site_announcements_tone_check CHECK ((tone = ANY (ARRAY['notice'::text, 'warning'::text])))
);


--
-- Name: TABLE site_announcements; Type: COMMENT; Schema: public; Owner: -
--

