--
-- Name: thread_transfers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.thread_transfers (
    transfer_id uuid NOT NULL,
    actor_id uuid,
    source_id uuid NOT NULL,
    target_id uuid NOT NULL,
    operation text NOT NULL,
    post_ids uuid[] NOT NULL,
    original_positions bigint[] NOT NULL,
    new_positions bigint[] NOT NULL,
    reply_links jsonb DEFAULT '[]'::jsonb NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    undone_at timestamp with time zone,
    CONSTRAINT thread_transfers_check CHECK ((source_id <> target_id)),
    CONSTRAINT thread_transfers_check1 CHECK (((cardinality(post_ids) = cardinality(original_positions)) AND (cardinality(post_ids) = cardinality(new_positions)))),
    CONSTRAINT thread_transfers_operation_check CHECK ((operation = ANY (ARRAY['move'::text, 'split'::text, 'merge'::text]))),
    CONSTRAINT thread_transfers_post_ids_check CHECK (((cardinality(post_ids) >= 1) AND (cardinality(post_ids) <= 1000))),
    CONSTRAINT thread_transfers_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 500)))
);


--
-- Name: TABLE thread_transfers; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.thread_transfers IS 'Bounded staff post transfers with original positions and severed reply links for safe reversal.';


--
