    deleted_at timestamp with time zone,
    deleted_by uuid,
    CONSTRAINT threads_moderation_state_check CHECK ((moderation_state = ANY (ARRAY['visible'::text, 'hidden'::text, 'locked'::text, 'deleted'::text]))),
    CONSTRAINT threads_permission_version_check CHECK ((permission_version > 0)),
    CONSTRAINT threads_version_check CHECK ((version > 0)),
    CONSTRAINT threads_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'members'::text, 'private'::text]))),
    CONSTRAINT threads_visibility_version_check CHECK ((visibility_version > 0))
)
WITH (fillfactor='90');


--
-- Name: TABLE threads; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.threads IS 'A thread: its category, author, title, state and last activity.';


